import 'dotenv/config';
import crypto from 'node:crypto';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import express from 'express';
import session from 'express-session';
import pg from 'pg';
import connectPgSimple from 'connect-pg-simple';
import cors from 'cors';
import helmet from 'helmet';
import rateLimit from 'express-rate-limit';
import multer from 'multer';
import bcrypt from 'bcryptjs';
import { PrismaClient } from '@prisma/client';
import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import { z } from 'zod';

const prisma=new PrismaClient();
const app=express();
const port=Number(process.env.PORT||4000);
const frontendUrl=process.env.FRONTEND_URL||'http://localhost:5173';
const production=process.env.NODE_ENV==='production';
if(!process.env.SESSION_SECRET||process.env.SESSION_SECRET.length<32){console.error('SESSION_SECRET must be configured with at least 32 characters.');process.exit(1)}
app.set('trust proxy',1);
app.use(helmet({crossOriginResourcePolicy:{policy:'cross-origin'}}));
app.use(cors({origin:frontendUrl.split(',').map(x=>x.trim()),credentials:true,methods:['GET','POST','PUT','PATCH','DELETE','OPTIONS'],allowedHeaders:['Content-Type','X-CSRF-Token']}));
app.use(express.json({limit:'1mb'}));
const pool=new pg.Pool({connectionString:process.env.DATABASE_URL,ssl:process.env.DATABASE_URL?.includes('sslmode=require')?{rejectUnauthorized:true}:undefined});
const PgStore=connectPgSimple(session);
app.use(session({store:new PgStore({pool,tableName:'user_sessions',createTableIfMissing:true}),name:'elsa.sid',secret:process.env.SESSION_SECRET,resave:false,saveUninitialized:false,cookie:{httpOnly:true,secure:production,sameSite:production?'none':'lax',maxAge:1000*60*60*10}}));
const loginLimiter=rateLimit({windowMs:15*60*1000,limit:10,standardHeaders:true,legacyHeaders:false,message:{error:'Too many sign-in attempts. Please wait and try again.'}});
const applicationLimiter=rateLimit({windowMs:60*60*1000,limit:12,standardHeaders:true,legacyHeaders:false,message:{error:'Too many applications were sent from this connection. Please try again later.'}});
const upload=multer({storage:multer.memoryStorage(),limits:{fileSize:8*1024*1024,files:8},fileFilter:(_req,file,cb)=>cb(null,/^image\/(jpeg|png|webp)$/.test(file.mimetype))});
const videoUpload=multer({storage:multer.memoryStorage(),limits:{fileSize:60*1024*1024,files:2},fileFilter:(_req,file,cb)=>cb(null,['video/mp4','video/webm','video/quicktime'].includes(file.mimetype))});
const pdfUpload=multer({storage:multer.memoryStorage(),limits:{fileSize:12*1024*1024,files:1},fileFilter:(_req,file,cb)=>cb(null,file.mimetype==='application/pdf')});

const safeUser=u=>({id:u.id,name:u.name,email:u.email,role:u.role,schoolDivision:u.schoolDivision||null,profileImageUrl:u.profileImageUrl||null});
function requireCsrf(req,res,next){if(!req.session.csrf||req.get('X-CSRF-Token')!==req.session.csrf)return res.status(403).json({error:'Session check failed. Refresh the page and try again.'});next()}
function allow(...roles){return async(req,res,next)=>{try{if(!req.session.userId)return res.status(401).json({error:'Sign in is required.'});const user=await prisma.user.findUnique({where:{id:req.session.userId}});if(!user||user.status!=='ACTIVE'){req.session.destroy(()=>{});return res.status(401).json({error:'This account is unavailable.'})}req.user=user;if(!roles.includes(user.role))return res.status(403).json({error:'Your account does not have access to this section.'});next()}catch(e){next(e)}}}
app.get('/api/health',async(_req,res)=>{try{await prisma.$queryRaw`SELECT 1`;await pool.query('SELECT 1');res.json({status:'ok',service:'elsa-school-api',database:'connected'})}catch(err){console.error('[health] database check failed',err);res.status(503).json({status:'error',service:'elsa-school-api',database:'unavailable'})}});
app.get('/api/auth/csrf',(req,res)=>{req.session.csrf=req.session.csrf||crypto.randomBytes(32).toString('hex');res.json({csrfToken:req.session.csrf})});
app.post('/api/auth/login',loginLimiter,requireCsrf,async(req,res,next)=>{try{const parsed=z.object({email:z.string().min(1).max(255),password:z.string().min(1).max(200),scope:z.enum(['STUDENT','TEACHER','ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS']).default('STUDENT')}).safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Enter your login ID and password.'});const identifier=parsed.data.email.trim();let user;if(parsed.data.scope==='STUDENT'&&!identifier.includes('@')){const student=await prisma.student.findUnique({where:{admissionNumber:identifier},include:{user:true}});user=student?.user||null}else{user=await prisma.user.findUnique({where:{email:identifier.toLowerCase()}})}const valid=user&&user.status==='ACTIVE'&&user.role===parsed.data.scope&&await bcrypt.compare(parsed.data.password,user.passwordHash);if(!valid)return res.status(401).json({error:'The login details do not match this portal.'});req.session.regenerate(err=>{if(err)return next(err);req.session.userId=user.id;req.session.csrf=crypto.randomBytes(32).toString('hex');req.session.save(saveErr=>{if(saveErr)return next(saveErr);res.json({user:safeUser(user),csrfToken:req.session.csrf})})})}catch(e){next(e)}});
app.get('/api/auth/me',allow('STUDENT','TEACHER','ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),(req,res)=>res.json({user:safeUser(req.user)}));
app.post('/api/auth/logout',requireCsrf,(req,res)=>req.session.destroy(err=>{if(err)return res.status(500).json({error:'Could not sign out.'});res.clearCookie('elsa.sid',{httpOnly:true,secure:production,sameSite:production?'none':'lax'});res.json({ok:true})}));

app.get('/api/public/site',async(_req,res,next)=>{try{const now=new Date();const [fees,gallery,notifications,events,feeDocument,pages,heroSlides]=await Promise.all([prisma.feeItem.findMany({where:{published:true},orderBy:{sortOrder:'asc'},take:5}),prisma.galleryImage.findMany({where:{published:true},orderBy:{sortOrder:'asc'},take:80}),prisma.announcement.findMany({where:{published:true,kind:{not:'AD'},audience:'ALL',AND:[{OR:[{startsAt:null},{startsAt:{lte:now}}]},{OR:[{endsAt:null},{endsAt:{gte:now}}]}]},orderBy:{createdAt:'desc'},take:8}),prisma.schoolEvent.findMany({where:{published:true,startsAt:{gte:now}},orderBy:{startsAt:'asc'},take:12}),prisma.feeDocument.findFirst({where:{published:true},orderBy:{updatedAt:'desc'}}),prisma.sitePage.findMany({where:{published:true},select:{slug:true,title:true,content:true}}),prisma.heroSlide.findMany({where:{published:true},orderBy:{sortOrder:'asc'},take:8})]);const ads=await prisma.announcement.findMany({where:{published:true,kind:'AD',AND:[{OR:[{startsAt:null},{startsAt:{lte:now}}]},{OR:[{endsAt:null},{endsAt:{gte:now}}]}]},orderBy:{createdAt:'desc'},take:3});res.json({fees,gallery,notifications,events,ads,feeDocument,pages,heroSlides})}catch(e){next(e)}});
const gradeDivision=grade=>grade==='Playgroup'||grade==='PP1'||grade==='PP2'||/^Grade [1-6]$/.test(grade)?'PRIMARY':'JUNIOR';
app.post('/api/public/applications',applicationLimiter,async(req,res,next)=>{try{const d=z.object({learnerName:z.string().min(2).max(120),learnerDateOfBirth:z.string().max(20).optional().or(z.literal('')),gender:z.enum(['MALE','FEMALE','OTHER']),division:z.enum(['PRIMARY','JUNIOR']),requestedGrade:z.enum(['Playgroup','PP1','PP2','Grade 1','Grade 2','Grade 3','Grade 4','Grade 5','Grade 6','Grade 7','Grade 8','Grade 9']),previousSchool:z.string().max(160).optional().or(z.literal('')),guardianName:z.string().min(2).max(120),guardianEmail:z.string().email().max(255),guardianPhone:z.string().min(7).max(30),additionalInformation:z.string().max(2500).optional().or(z.literal(''))}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Check the learner, school division, grade and guardian contact details.'});if(gradeDivision(d.data.requestedGrade)!==d.data.division)return res.status(400).json({error:'The selected grade does not belong to the chosen school division.'});const application=await prisma.studentApplication.create({data:{...d.data}});res.status(201).json({application:{id:application.id,status:application.status,division:application.division},message:'Application received. The admissions team for this school division will contact the guardian.'})}catch(e){next(e)}});
app.get('/api/admin/applications',allow('ADMIN','SUPER_ADMIN'),async(req,res,next)=>{try{if(req.user.role==='ADMIN'&&!req.user.schoolDivision)return res.status(403).json({error:'This administrator has no school division assigned.'});const applications=await prisma.studentApplication.findMany({where:req.user.role==='ADMIN'?{division:req.user.schoolDivision}:{},orderBy:{createdAt:'desc'},take:300});res.json({applications})}catch(e){next(e)}});
app.patch('/api/admin/applications/:id',allow('ADMIN','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const d=z.object({status:z.enum(['PENDING','UNDER_REVIEW','ACCEPTED','DECLINED']),adminNote:z.string().max(1500).optional().nullable(),registrationNumber:z.string().min(3).max(40).optional(),temporaryPassword:z.string().min(12).max(128).optional()}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Choose a status and provide valid admission login details when approving.'});const current=await prisma.studentApplication.findUnique({where:{id:req.params.id}});if(!current)return res.status(404).json({error:'Application not found.'});if(req.user.role==='ADMIN'&&(!req.user.schoolDivision||current.division!==req.user.schoolDivision))return res.status(403).json({error:'This application belongs to the other school division.'});if(current.status==='ACCEPTED')return res.status(409).json({error:`This application has already been admitted with registration number ${current.registrationNumber||'on record'}.`});if(d.data.status!=='ACCEPTED'){const application=await prisma.studentApplication.update({where:{id:current.id},data:{status:d.data.status,adminNote:d.data.adminNote||null,reviewedAt:new Date()}});return res.json({application})}if(!d.data.registrationNumber||!d.data.temporaryPassword)return res.status(400).json({error:'Enter the registration number and a temporary password before approving.'});await seedGradeGroups();let classGroup=await prisma.classGroup.findFirst({where:{yearLevel:current.requestedGrade,division:current.division}});if(!classGroup)classGroup=await prisma.classGroup.create({data:{name:current.requestedGrade,yearLevel:current.requestedGrade,division:current.division}});const safeRegistration=d.data.registrationNumber.trim();const localEmail=`student-${safeRegistration.toLowerCase().replace(/[^a-z0-9.-]/g,'-')}@login.invalid`;const passwordHash=await bcrypt.hash(d.data.temporaryPassword,12);const result=await prisma.$transaction(async tx=>{const user=await tx.user.create({data:{name:current.learnerName,email:localEmail,passwordHash,role:'STUDENT',schoolDivision:current.division}});const student=await tx.student.create({data:{userId:user.id,admissionNumber:safeRegistration,yearLevel:current.requestedGrade,gender:current.gender,dateOfBirth:current.learnerDateOfBirth?new Date(`${current.learnerDateOfBirth}T00:00:00.000Z`):null,guardianName:current.guardianName,guardianPhone:current.guardianPhone,guardianEmail:current.guardianEmail,classGroupId:classGroup.id}});const application=await tx.studentApplication.update({where:{id:current.id},data:{status:'ACCEPTED',registrationNumber:safeRegistration,adminNote:d.data.adminNote||null,reviewedAt:new Date()}});return {application,student}});res.json({application:result.application,student:{id:result.student.id,registrationNumber:result.student.admissionNumber,className:classGroup.name}})}catch(e){if(e.code==='P2002')return res.status(409).json({error:'That registration number, email or account already exists.'});next(e)}});
app.get('/api/admin/site',allow('ADMIN','SUPER_ADMIN'),async(_req,res,next)=>{try{const [fees,gallery,pages,announcements,events,feeDocument,heroSlides]=await Promise.all([prisma.feeItem.findMany({orderBy:{sortOrder:'asc'}}),prisma.galleryImage.findMany({orderBy:{sortOrder:'asc'}}),prisma.sitePage.findMany({orderBy:{slug:'asc'}}),prisma.announcement.findMany({orderBy:{createdAt:'desc'},take:50}),prisma.schoolEvent.findMany({orderBy:{startsAt:'desc'},take:50}),prisma.feeDocument.findFirst({orderBy:{updatedAt:'desc'}}),prisma.heroSlide.findMany({orderBy:{sortOrder:'asc'}})]);res.json({fees,gallery,pages,announcements,events,feeDocument,heroSlides})}catch(e){next(e)}});
const feeSchema=z.object({fees:z.array(z.object({id:z.string().optional(),label:z.string().min(1).max(120),displayAmount:z.string().max(100),category:z.string().max(80).optional(),published:z.boolean(),sortOrder:z.number().int().optional()})).max(40)});
app.put('/api/admin/fees',allow('FINANCE','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const parsed=feeSchema.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Check each fee item and try again.'});await prisma.$transaction(async tx=>{await tx.feeItem.deleteMany();await tx.feeItem.createMany({data:parsed.data.fees.map((x,i)=>({label:x.label.trim(),displayAmount:x.displayAmount.trim(),category:x.category||'School fees',published:x.published,sortOrder:x.sortOrder??i}))});if(req.body.feeDocument?.id)await tx.feeDocument.update({where:{id:req.body.feeDocument.id},data:{published:!!req.body.feeDocument.published}})});const [fees,feeDocument]=await Promise.all([prisma.feeItem.findMany({orderBy:{sortOrder:'asc'}}),prisma.feeDocument.findFirst({orderBy:{updatedAt:'desc'}})]);res.json({site:{fees,feeDocument}})}catch(e){next(e)}});
const gallerySchema=z.object({gallery:z.array(z.object({id:z.string().optional(),imageUrl:z.string().url(),altText:z.string().max(200).optional().nullable(),caption:z.string().max(160).optional().nullable(),description:z.string().max(1200).optional().nullable(),category:z.string().min(1).max(60),mediaType:z.enum(['IMAGE','VIDEO']).optional(),published:z.boolean(),sortOrder:z.number().int().optional()})).max(100)});
app.put('/api/admin/gallery',allow('ADMIN','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const parsed=gallerySchema.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'One or more gallery items are invalid.'});await prisma.$transaction([prisma.galleryImage.deleteMany(),prisma.galleryImage.createMany({data:parsed.data.gallery.map((x,i)=>({imageUrl:x.imageUrl,altText:x.altText||null,caption:x.caption||null,description:x.description||null,category:x.category,mediaType:x.mediaType||'IMAGE',published:x.published,sortOrder:x.sortOrder??i}))})]);const gallery=await prisma.galleryImage.findMany({orderBy:{sortOrder:'asc'}});res.json({site:{gallery}})}catch(e){next(e)}});

const heroSchema=z.object({slides:z.array(z.object({id:z.string().optional(),imageUrl:z.string().url(),title:z.string().min(1).max(140),caption:z.string().max(240).optional().nullable(),division:z.string().max(100).optional().nullable(),altText:z.string().max(200).optional().nullable(),published:z.boolean(),sortOrder:z.number().int().optional()})).max(8)});
app.put('/api/admin/hero-slides',allow('ADMIN','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const parsed=heroSchema.safeParse(req.body);if(!parsed.success)return res.status(400).json({error:'Check the homepage slide details and try again.'});await prisma.$transaction([prisma.heroSlide.deleteMany(),prisma.heroSlide.createMany({data:parsed.data.slides.map((x,i)=>({imageUrl:x.imageUrl,title:x.title.trim(),caption:x.caption||null,division:x.division||null,altText:x.altText||null,published:x.published,sortOrder:x.sortOrder??i}))})]);const heroSlides=await prisma.heroSlide.findMany({orderBy:{sortOrder:'asc'}});res.json({site:{heroSlides}})}catch(e){next(e)}});

const s3=process.env.R2_ACCOUNT_ID&&process.env.R2_ACCESS_KEY_ID&&process.env.R2_SECRET_ACCESS_KEY?new S3Client({region:'auto',endpoint:`https://${process.env.R2_ACCOUNT_ID}.r2.cloudflarestorage.com`,credentials:{accessKeyId:process.env.R2_ACCESS_KEY_ID,secretAccessKey:process.env.R2_SECRET_ACCESS_KEY}}):null;
const ext={ 'image/jpeg':'jpg','image/png':'png','image/webp':'webp' };
app.post('/api/admin/gallery/upload',allow('ADMIN','SUPER_ADMIN'),requireCsrf,upload.array('images',8),async(req,res,next)=>{try{if(!req.files?.length)return res.status(400).json({error:'Choose image files to upload.'});if(!s3||!process.env.R2_BUCKET||!process.env.R2_PUBLIC_BASE_URL)return res.status(503).json({error:'Image uploads need the school media storage settings configured.'});const category=z.string().min(1).max(60).catch('School life').parse(req.body.category);const urls=[];for(const file of req.files){const key=`gallery/${new Date().toISOString().slice(0,10)}/${crypto.randomUUID()}.${ext[file.mimetype]}`;await s3.send(new PutObjectCommand({Bucket:process.env.R2_BUCKET,Key:key,Body:file.buffer,ContentType:file.mimetype,CacheControl:'public, max-age=31536000, immutable'}));urls.push({imageUrl:`${process.env.R2_PUBLIC_BASE_URL.replace(/\/$/,'')}/${key}`,fileName:file.originalname,category})}res.status(201).json({uploads:urls})}catch(e){next(e)}});
app.post('/api/admin/gallery/upload-video',allow('ADMIN','SUPER_ADMIN'),requireCsrf,videoUpload.array('videos',2),async(req,res,next)=>{try{if(!req.files?.length)return res.status(400).json({error:'Choose MP4, WebM or MOV videos.'});if(!s3||!process.env.R2_BUCKET||!process.env.R2_PUBLIC_BASE_URL)return res.status(503).json({error:'Video uploads need the school media storage settings configured.'});const category=z.string().min(1).max(60).catch('School life').parse(req.body.category);const uploads=[];for(const file of req.files){const extByMime={'video/mp4':'mp4','video/webm':'webm','video/quicktime':'mov'};const key=`gallery/videos/${new Date().toISOString().slice(0,10)}/${crypto.randomUUID()}.${extByMime[file.mimetype]}`;await s3.send(new PutObjectCommand({Bucket:process.env.R2_BUCKET,Key:key,Body:file.buffer,ContentType:file.mimetype,CacheControl:'public, max-age=86400'}));uploads.push({imageUrl:`${process.env.R2_PUBLIC_BASE_URL.replace(/\/$/,'')}/${key}`,fileName:file.originalname,category,mediaType:'VIDEO'})}res.status(201).json({uploads})}catch(e){next(e)}});
app.put('/api/portal/profile',allow('STUDENT','TEACHER','ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),requireCsrf,async(req,res,next)=>{try{const d=z.object({name:z.string().min(2).max(120),email:z.string().email().max(255)}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Enter a valid name and email address.'});const user=await prisma.user.update({where:{id:req.user.id},data:{name:d.data.name.trim(),email:d.data.email.trim().toLowerCase()}});res.json({user:safeUser(user)})}catch(e){if(e.code==='P2002')return res.status(409).json({error:'That email is already used by another account.'});next(e)}});
app.post('/api/portal/profile/photo',allow('STUDENT','TEACHER','ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),requireCsrf,upload.single('image'),async(req,res,next)=>{try{if(!req.file)return res.status(400).json({error:'Choose a JPG, PNG or WebP photo.'});if(!s3||!process.env.R2_BUCKET||!process.env.R2_PUBLIC_BASE_URL)return res.status(503).json({error:'Profile photo storage needs to be configured.'});const extension={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[req.file.mimetype];const key=`profiles/${req.user.id}/${crypto.randomUUID()}.${extension}`;await s3.send(new PutObjectCommand({Bucket:process.env.R2_BUCKET,Key:key,Body:req.file.buffer,ContentType:req.file.mimetype,CacheControl:'public, max-age=86400'}));const user=await prisma.user.update({where:{id:req.user.id},data:{profileImageUrl:`${process.env.R2_PUBLIC_BASE_URL.replace(/\/$/,'')}/${key}`}});res.json({user:safeUser(user)})}catch(e){next(e)}});
async function messageContactIds(user){if(user.role==='SUPER_ADMIN')return (await prisma.user.findMany({where:{status:'ACTIVE',id:{not:user.id}},select:{id:true}})).map(x=>x.id);if(user.role==='ADMIN')return (await prisma.user.findMany({where:{role:'TEACHER',status:'ACTIVE',schoolDivision:user.schoolDivision},select:{id:true}})).map(x=>x.id);if(user.role==='STUDENT'){const student=await prisma.student.findUnique({where:{userId:user.id},select:{classGroupId:true}});if(!student?.classGroupId)return [];const links=await prisma.classTeaching.findMany({where:{classGroupId:student.classGroupId},select:{teacher:{select:{userId:true}}}});return links.map(x=>x.teacher.userId)}if(['FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'].includes(user.role)){return (await prisma.user.findMany({where:{status:'ACTIVE',id:{not:user.id},...(user.schoolDivision?{schoolDivision:user.schoolDivision}:{})},select:{id:true}})).map(x=>x.id)}if(user.role==='TEACHER'){const teacher=await prisma.teacher.findUnique({where:{userId:user.id},select:{id:true}});if(!teacher)return [];const links=await prisma.classTeaching.findMany({where:{teacherId:teacher.id},select:{classGroupId:true}});const ids=(await prisma.student.findMany({where:{classGroupId:{in:links.map(x=>x.classGroupId)}},select:{userId:true}})).map(x=>x.userId);return [...new Set(ids)]}return []}
app.get('/api/portal/contacts',allow('STUDENT','TEACHER','ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),async(req,res,next)=>{try{const ids=await messageContactIds(req.user);const users=ids.length?await prisma.user.findMany({where:{id:{in:ids},status:'ACTIVE'},select:{id:true,name:true,role:true,profileImageUrl:true},orderBy:{name:'asc'},take:500}):[];res.json({users})}catch(e){next(e)}});
app.get('/api/portal/messages',allow('STUDENT','TEACHER','ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),async(req,res,next)=>{try{const messages=await prisma.message.findMany({where:{OR:[{senderId:req.user.id},{recipientId:req.user.id},{recipientId:null,sender:{role:'SUPER_ADMIN'}}]},include:{sender:{select:{id:true,name:true,role:true,profileImageUrl:true}},recipient:{select:{id:true,name:true,role:true}}},orderBy:{createdAt:'desc'},take:200});res.json({messages})}catch(e){next(e)}});
app.post('/api/portal/messages',allow('STUDENT','TEACHER','ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),requireCsrf,async(req,res,next)=>{try{const d=z.object({recipientId:z.string().optional().nullable(),subject:z.string().max(160).optional(),body:z.string().min(1).max(6000)}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Write a message before sending.'});if(!d.data.recipientId){if(req.user.role!=='SUPER_ADMIN')return res.status(403).json({error:'Only the Super Admin can send a school-wide message.'})}else{const ids=await messageContactIds(req.user);if(!ids.includes(d.data.recipientId))return res.status(403).json({error:'You can only message users connected to your school role.'})}const message=await prisma.message.create({data:{senderId:req.user.id,recipientId:d.data.recipientId||null,subject:d.data.subject?.trim()||null,body:d.data.body.trim()},include:{sender:{select:{id:true,name:true,role:true,profileImageUrl:true}},recipient:{select:{id:true,name:true,role:true}}}});res.status(201).json({message})}catch(e){next(e)}});
app.patch('/api/portal/messages/:id/read',allow('STUDENT','TEACHER','ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),requireCsrf,async(req,res,next)=>{try{const updated=await prisma.message.updateMany({where:{id:req.params.id,OR:[{recipientId:req.user.id},{recipientId:null,sender:{role:'SUPER_ADMIN'}}]},data:{readAt:new Date()}});res.json({ok:updated.count===1})}catch(e){next(e)}});
app.patch('/api/portal/presence',allow('STUDENT','TEACHER','ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),async(req,res,next)=>{try{await prisma.user.update({where:{id:req.user.id},data:{lastSeenAt:new Date()}});res.json({ok:true})}catch(e){next(e)}});
