app.get('/api/admin/academics',allow('ADMIN','SUPER_ADMIN'),async(req,res,next)=>{try{await seedGradeGroups();const division=req.user.role==='ADMIN'?req.user.schoolDivision:null;if(req.user.role==='ADMIN'&&!division)return res.status(403).json({error:'This administrator has no school division assigned.'});const where=division?{division}:{};const [classes,teachers]=await Promise.all([prisma.classGroup.findMany({where,include:{_count:{select:{students:true}},subjects:{orderBy:{name:'asc'}},classTeaching:{include:{subject:true,teacher:{include:{user:{select:{id:true,name:true,email:true}}}}}}},orderBy:{yearLevel:'asc'}}),prisma.teacher.findMany({where:division?{user:{schoolDivision:division}}:{},include:{user:{select:{id:true,name:true,email:true,schoolDivision:true}}},orderBy:{user:{name:'asc'}}})]);res.json({classes,teachers})}catch(e){next(e)}});
app.post('/api/admin/classes',allow('ADMIN','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const d=z.object({name:z.string().min(2).max(80),yearLevel:z.string().min(1).max(40),division:z.enum(['PRIMARY','JUNIOR']),subjects:z.array(z.string().min(1).max(100)).max(30).default([])}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Add a class name, grade and division.'});if(gradeDivision(d.data.yearLevel)!==d.data.division)return res.status(400).json({error:'That grade does not belong to the selected school division.'});if(req.user.role==='ADMIN'&&d.data.division!==req.user.schoolDivision)return res.status(403).json({error:'You can only create classes for your assigned school division.'});const group=await prisma.classGroup.create({data:{name:d.data.name,yearLevel:d.data.yearLevel,division:d.data.division,subjects:{create:d.data.subjects.map(name=>({name:name.trim()}))}}});res.status(201).json({classGroup:group})}catch(e){if(e.code==='P2002')return res.status(409).json({error:'That class name already exists.'});next(e)}});
app.post('/api/admin/classes/:id/assignments',allow('ADMIN','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const d=z.object({subjectName:z.string().min(1).max(100),teacherId:z.string().min(1)}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Choose a subject and teacher.'});const group=await prisma.classGroup.findUnique({where:{id:req.params.id}});const teacher=await prisma.teacher.findUnique({where:{id:d.data.teacherId},include:{user:true}});if(!group||!teacher)return res.status(404).json({error:'Class or teacher not found.'});if(req.user.role==='ADMIN'&&group.division!==req.user.schoolDivision)return res.status(403).json({error:'This class belongs to the other school division.'});if(teacher.user.schoolDivision&&teacher.user.schoolDivision!==group.division)return res.status(400).json({error:'A teacher can only be assigned within their school division.'});const subject=await prisma.subject.upsert({where:{name_classGroupId:{name:d.data.subjectName,classGroupId:group.id}},create:{name:d.data.subjectName,classGroupId:group.id},update:{}});const assignment=await prisma.classTeaching.upsert({where:{classGroupId_subjectId:{classGroupId:group.id,subjectId:subject.id}},create:{classGroupId:group.id,subjectId:subject.id,teacherId:teacher.id},update:{teacherId:teacher.id},include:{subject:true,teacher:{include:{user:{select:{id:true,name:true,email:true}}}}}});res.json({assignment})}catch(e){next(e)}});
app.patch('/api/admin/students/:id/class',allow('ADMIN','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const d=z.object({classGroupId:z.string().min(1)}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Choose a valid class.'});const [student,group]=await Promise.all([prisma.student.findUnique({where:{id:req.params.id},include:{classGroup:true}}),prisma.classGroup.findUnique({where:{id:d.data.classGroupId}})]);if(!student||!group)return res.status(404).json({error:'Student or class not found.'});if(req.user.role==='ADMIN'&&(group.division!==req.user.schoolDivision||(student.classGroup&&student.classGroup.division!==req.user.schoolDivision)))return res.status(403).json({error:'You can only move learners within your assigned school division.'});const updated=await prisma.student.update({where:{id:student.id},data:{classGroupId:group.id,yearLevel:group.yearLevel||group.name}});res.json({student:updated})}catch(e){next(e)}});
