app.get('/api/admin/students',allow('ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),async(req,res,next)=>{try{const division=req.user.role==='ADMIN'?req.user.schoolDivision:req.query.division;const q=String(req.query.q||'').trim();const grade=String(req.query.grade||'');if(req.user.role==='ADMIN'&&!division)return res.status(403).json({error:'This administrator has no school division assigned.'});const where={...studentScopeWhere(req,division),...(grade?{yearLevel:grade}:{}),...(req.user.role==='BOARDING_MASTER'?{gender:'MALE'}:req.user.role==='BOARDING_MISTRESS'?{gender:'FEMALE'}:{}),...(q?{OR:[{admissionNumber:{contains:q,mode:'insensitive'}},{user:{is:{name:{contains:q,mode:'insensitive'}}}},{guardianPhone:{contains:q}},{yearLevel:{contains:q,mode:'insensitive'}}]}:{})};const students=await prisma.student.findMany({where,include:{user:{select:{id:true,name:true,email:true,profileImageUrl:true,lastSeenAt:true,status:true}},classGroup:{select:{id:true,name:true,yearLevel:true,division:true}}},orderBy:{user:{name:'asc'}},take:300});res.json({students:students.map(s=>({...s,online:!!s.user.lastSeenAt&&Date.now()-new Date(s.user.lastSeenAt).getTime()<120000}))})}catch(e){next(e)}});
app.get('/api/admin/students/:id',allow('ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),async(req,res,next)=>{try{const s=await prisma.student.findUnique({where:{id:req.params.id},include:{user:{select:{id:true,name:true,email:true,profileImageUrl:true,lastSeenAt:true}},classGroup:{include:{classTeaching:{include:{subject:true,teacher:{include:{user:{select:{id:true,name:true}}}}}}}},grades:{include:{subject:true},orderBy:{createdAt:'asc'}},feeEntries:true,feePayments:{orderBy:{createdAt:'desc'}}}});if(!s)return res.status(404).json({error:'Student record not found.'});if(req.user.role==='ADMIN'&&s.classGroup?.division!==req.user.schoolDivision)return res.status(404).json({error:'Student record not found in your school division.'});if(req.user.role==='BOARDING_MASTER'&&s.gender!=='MALE'||req.user.role==='BOARDING_MISTRESS'&&s.gender!=='FEMALE')return res.status(404).json({error:'Student record not found.'});const gradeRows=s.grades.map(g=>({...g}));const bySubject=Object.values(gradeRows.reduce((a,g)=>{const k=g.subject?.name||'Other';a[k]??={subject:k,score:0,max:0,count:0};a[k].score+=Number(g.score);a[k].max+=Number(g.maxScore);a[k].count++;return a},{})).map(x=>({...x,percent:x.max?Math.round(x.score/x.max*100):0}));const overall=bySubject.length?Math.round(bySubject.reduce((n,x)=>n+x.percent,0)/bySubject.length):null;const schedule=await prisma.feeSchedule.findFirst({where:{division:s.classGroup?.division||s.user.schoolDivision,yearLevel:s.yearLevel,published:true},include:{sections:true},orderBy:{academicYear:'desc'}});const paid=s.feeEntries.reduce((n,x)=>n+Number(x.amountPaid),0)+s.feePayments.filter(x=>x.status==='CONFIRMED').reduce((n,x)=>n+Number(x.amount),0);const scheduleDue=schedule?.sections.reduce((n,x)=>n+Number(x.amount),0)||0;const schedulePaid=schedule?s.feePayments.filter(x=>x.status==='CONFIRMED'&&x.academicYear===schedule.academicYear&&x.term===schedule.term).reduce((n,x)=>n+Number(x.amount),0):0;res.json({student:{...s,feeSchedule:schedule,online:!!s.user.lastSeenAt&&Date.now()-new Date(s.user.lastSeenAt).getTime()<120000,academicSummary:{subjects:bySubject,overall},feeSummary:{paid,pending:s.feePayments.filter(x=>x.status==='PENDING').reduce((n,x)=>n+Number(x.amount),0),balance:schedule?Math.max(0,scheduleDue-schedulePaid):s.feeEntries.reduce((n,x)=>n+Number(x.amountDue)-Number(x.amountPaid),0)}}})}catch(e){next(e)}});
app.patch('/api/admin/students/:id',allow('ADMIN','SUPER_ADMIN','BOARDING_MASTER','BOARDING_MISTRESS'),requireCsrf,async(req,res,next)=>{try{const current=await prisma.student.findUnique({where:{id:req.params.id},include:{classGroup:true}});if(!current)return res.status(404).json({error:'Student record not found.'});if(req.user.role==='ADMIN'&&current.classGroup?.division!==req.user.schoolDivision)return res.status(404).json({error:'Student record not found in your division.'});if(req.user.role==='BOARDING_MASTER'&&current.gender!=='MALE'||req.user.role==='BOARDING_MISTRESS'&&current.gender!=='FEMALE')return res.status(404).json({error:'Student record not found.'});const schema=req.user.role.startsWith('BOARDING_')?z.object({dormitoryName:z.string().max(100).nullable().optional(),bedNumber:z.string().max(40).nullable().optional(),boardingStatus:z.string().max(80).nullable().optional()}).strict():z.object({name:z.string().min(2).max(120).optional(),email:z.string().email().max(255).optional(),admissionNumber:z.string().min(2).max(40).optional(),gender:z.enum(['MALE','FEMALE','OTHER']).optional().nullable(),dateOfBirth:z.string().optional().nullable(),guardianName:z.string().max(120).optional().nullable(),guardianPhone:z.string().max(30).optional().nullable(),guardianEmail:z.string().email().max(255).optional().nullable().or(z.literal('')),boardingStatus:z.string().max(80).optional().nullable(),dormitoryName:z.string().max(100).optional().nullable(),bedNumber:z.string().max(40).optional().nullable()}).strict();const d=schema.safeParse(req.body);if(!d.success)return res.status(400).json({error:'Only permitted student profile fields can be changed. Academic grades are teacher-managed.'});const {name,email,...fields}=d.data;const student=await prisma.$transaction(async tx=>{if(name||email)await tx.user.update({where:{id:current.userId},data:{...(name?{name:name.trim()}:{}),...(email?{email:email.trim().toLowerCase()}:{})}});return tx.student.update({where:{id:current.id},data:{...fields,...(fields.dateOfBirth!==undefined?{dateOfBirth:fields.dateOfBirth?new Date(fields.dateOfBirth):null}:{}),...(fields.guardianEmail===''?{guardianEmail:null}:{})},include:{user:{select:{id:true,name:true,email:true,profileImageUrl:true}},classGroup:true}})});res.json({student})}catch(e){if(e.code==='P2002')return res.status(409).json({error:'That admission number or email is already in use.'});next(e)}});
app.post('/api/admin/users/:id/photo',allow('ADMIN','SUPER_ADMIN'),requireCsrf,upload.single('image'),async(req,res,next)=>{try{const target=await prisma.user.findUnique({where:{id:req.params.id},include:{student:{include:{classGroup:true}}}});if(!target||target.role!=='STUDENT'||req.user.role==='ADMIN'&&target.student?.classGroup?.division!==req.user.schoolDivision)return res.status(404).json({error:'Student account not found in your division.'});if(!req.file)return res.status(400).json({error:'Choose a JPG, PNG or WebP photo.'});if(!s3||!process.env.R2_BUCKET||!process.env.R2_PUBLIC_BASE_URL)return res.status(503).json({error:'Profile photo storage needs to be configured.'});const extension={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[req.file.mimetype];const key=`profiles/${target.id}/${crypto.randomUUID()}.${extension}`;await s3.send(new PutObjectCommand({Bucket:process.env.R2_BUCKET,Key:key,Body:req.file.buffer,ContentType:req.file.mimetype,CacheControl:'public, max-age=86400'}));const user=await prisma.user.update({where:{id:target.id},data:{profileImageUrl:`${process.env.R2_PUBLIC_BASE_URL.replace(/\/$/,'')}/${key}`}});res.json({user:safeUser(user)})}catch(e){next(e)}});
