app.post('/api/admin/fee-structures',allow('FINANCE','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const d=z.object({division:z.enum(['PRIMARY','JUNIOR']),yearLevel:z.string().min(1).max(40),academicYear:z.string().min(4).max(12),term:z.string().min(1).max(30),published:z.boolean(),sections:z.array(z.object({label:z.string().min(1).max(100),amount:z.number().nonnegative()})).min(1).max(30)}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Add a division, grade, year, term and at least one fee section.'});const schedule=await prisma.feeSchedule.upsert({where:{division_yearLevel_academicYear_term:{division:d.data.division,yearLevel:d.data.yearLevel,academicYear:d.data.academicYear,term:d.data.term}},create:{division:d.data.division,yearLevel:d.data.yearLevel,academicYear:d.data.academicYear,term:d.data.term,published:d.data.published,createdById:req.user.id,sections:{create:d.data.sections.map((x,i)=>({...x,sortOrder:i}))}},update:{published:d.data.published,sections:{deleteMany:{},create:d.data.sections.map((x,i)=>({...x,sortOrder:i}))}},include:{sections:{orderBy:{sortOrder:'asc'}}}});res.json({schedule})}catch(e){next(e)}});
app.get('/api/portal/fees',allow('STUDENT'),async(req,res,next)=>{try{const student=await prisma.student.findUnique({where:{userId:req.user.id},include:{classGroup:true,feeEntries:true,feePayments:{orderBy:{createdAt:'desc'}}}});if(!student)return res.status(404).json({error:'Student record is not linked to this account.'});const schedule=await prisma.feeSchedule.findFirst({where:{division:student.classGroup?.division||req.user.schoolDivision,yearLevel:student.yearLevel,published:true},include:{sections:{orderBy:{sortOrder:'asc'}}},orderBy:{academicYear:'desc'}});res.json({student,schedule})}catch(e){next(e)}});
app.post('/api/portal/fees/payments',allow('STUDENT'),requireCsrf,async(req,res,next)=>{try{const d=z.object({academicYear:z.string().min(4).max(12),term:z.string().min(1).max(30),purpose:z.string().min(2).max(100),amount:z.number().positive(),transactionReference:z.string().max(100).optional(),note:z.string().max(500).optional()}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Enter the payment term, purpose and amount.'});const student=await prisma.student.findUnique({where:{userId:req.user.id}});if(!student)return res.status(404).json({error:'Student record not found.'});const payment=await prisma.feePayment.create({data:{...d.data,transactionReference:d.data.transactionReference||null,studentId:student.id}});res.status(201).json({payment})}catch(e){if(e.code==='P2002')return res.status(409).json({error:'That payment reference has already been submitted.'});next(e)}});
app.get('/api/finance/fee-content',allow('FINANCE','SUPER_ADMIN'),async(_req,res,next)=>{try{const [fees,feeDocument]=await Promise.all([prisma.feeItem.findMany({orderBy:{sortOrder:'asc'}}),prisma.feeDocument.findFirst({orderBy:{updatedAt:'desc'}})]);res.json({site:{fees,feeDocument}})}catch(e){next(e)}});
app.get('/api/finance/payments',allow('FINANCE','SUPER_ADMIN'),async(req,res,next)=>{try{const where=req.user.role==='ADMIN'?{student:{classGroup:{division:req.user.schoolDivision}}}:{};const payments=await prisma.feePayment.findMany({where,include:{student:{include:{user:{select:{name:true}},classGroup:true}}},orderBy:{createdAt:'desc'},take:500});res.json({payments})}catch(e){next(e)}});
app.patch('/api/finance/payments/:id',allow('FINANCE','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const d=z.object({status:z.enum(['CONFIRMED','REJECTED']),note:z.string().max(500).optional()}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Choose whether to confirm or reject the payment.'});const payment=await prisma.feePayment.update({where:{id:req.params.id},data:{status:d.data.status,note:d.data.note||null,verifiedById:req.user.id,paidAt:d.data.status==='CONFIRMED'?new Date():null}});res.json({payment})}catch(e){next(e)}});
app.get('/api/admin/users',allow('ADMIN','SUPER_ADMIN'),async(req,res,next)=>{try{if(req.user.role==='ADMIN'&&!req.user.schoolDivision)return res.status(403).json({error:'This administrator has no school division assigned.'});const base={role:{not:'SUPER_ADMIN'}};const where=req.user.role==='ADMIN'?{role:{notIn:['SUPER_ADMIN','FINANCE']},OR:[{schoolDivision:req.user.schoolDivision},{student:{is:{classGroup:{is:{division:req.user.schoolDivision}}}}}]}:base;const users=await prisma.user.findMany({where,select:{id:true,name:true,email:true,role:true,status:true,schoolDivision:true,profileImageUrl:true,lastSeenAt:true,student:{select:{id:true,admissionNumber:true,yearLevel:true,gender:true,dateOfBirth:true,guardianName:true,guardianPhone:true,guardianEmail:true,boardingStatus:true,dormitoryName:true,bedNumber:true,classGroupId:true,classGroup:{select:{name:true,division:true}}}},createdAt:true},orderBy:{createdAt:'desc'},take:500});res.json({users})}catch(e){next(e)}});
app.post('/api/admin/users',allow('ADMIN','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const d=z.object({name:z.string().min(2).max(120),email:z.string().email(),password:z.string().min(12).max(128),role:z.enum(['STUDENT','TEACHER','ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS']),admissionNumber:z.string().optional(),staffNumber:z.string().optional(),schoolDivision:z.enum(['PRIMARY','JUNIOR']).optional(),yearLevel:z.string().optional(),classGroupId:z.string().optional(),gender:z.enum(['MALE','FEMALE','OTHER']).optional(),dateOfBirth:z.string().max(30).optional().nullable(),guardianName:z.string().max(120).optional().nullable(),guardianPhone:z.string().max(30).optional().nullable(),guardianEmail:z.string().email().max(255).optional().nullable().or(z.literal('')),boardingStatus:z.string().max(80).optional().nullable(),dormitoryName:z.string().max(100).optional().nullable(),bedNumber:z.string().max(40).optional().nullable()}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Check the account details and required school division.'});if(d.data.role==='ADMIN'&&req.user.role!=='SUPER_ADMIN')return res.status(403).json({error:'Only the Super Admin can create school administrators.'});if(d.data.role==='FINANCE'&&req.user.role!=='SUPER_ADMIN')return res.status(403).json({error:'Only the Super Admin can create Finance accounts.'});if(req.user.role==='ADMIN'&&!['STUDENT','TEACHER','BOARDING_MASTER','BOARDING_MISTRESS'].includes(d.data.role))return res.status(403).json({error:'School administrators can create student, teacher and boarding accounts only.'});if(d.data.role==='STUDENT'&&(!d.data.admissionNumber||!d.data.classGroupId||!d.data.gender))return res.status(400).json({error:'Student accounts require an admission number, grade and gender.'});if(d.data.role==='ADMIN'&&!d.data.schoolDivision)return res.status(400).json({error:'Choose Primary or Junior Secondary for this administrator.'});if(req.user.role==='SUPER_ADMIN'&&['TEACHER','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'].includes(d.data.role)&&!d.data.schoolDivision)return res.status(400).json({error:'Choose the school division for this staff account.'});const group=d.data.role==='STUDENT'?await prisma.classGroup.findUnique({where:{id:d.data.classGroupId}}):null;if(d.data.role==='STUDENT'&&!group)return res.status(400).json({error:'Choose an existing grade/class before creating the student account.'});const schoolDivision=d.data.role==='STUDENT'?group.division:req.user.role==='ADMIN'?req.user.schoolDivision:d.data.schoolDivision||null;if(req.user.role==='ADMIN'&&d.data.role==='STUDENT'&&group.division!==req.user.schoolDivision)return res.status(403).json({error:'You can only create students in your assigned school division.'});const hash=await bcrypt.hash(d.data.password,12);const created=await prisma.$transaction(async tx=>{const u=await tx.user.create({data:{name:d.data.name.trim(),email:d.data.email.trim().toLowerCase(),passwordHash:hash,role:d.data.role,schoolDivision}});let student=null;if(d.data.role==='STUDENT')student=await tx.student.create({data:{userId:u.id,admissionNumber:d.data.admissionNumber.trim(),yearLevel:group.yearLevel||group.name,classGroupId:group.id,gender:d.data.gender,dateOfBirth:d.data.dateOfBirth?new Date(d.data.dateOfBirth):null,guardianName:d.data.guardianName||null,guardianPhone:d.data.guardianPhone||null,guardianEmail:d.data.guardianEmail||null,boardingStatus:d.data.boardingStatus||null,dormitoryName:d.data.dormitoryName||null,bedNumber:d.data.bedNumber||null}});if(d.data.role==='TEACHER')await tx.teacher.create({data:{userId:u.id,staffNumber:d.data.staffNumber||null}});return {user:safeUser(u),student}});res.status(201).json({user:{...created.user,student:created.student}})}catch(e){if(e.code==='P2002')return res.status(409).json({error:'That email, admission number or staff number is already in use.'});next(e)}});
app.patch('/api/admin/users/:id/division',allow('SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const d=z.object({schoolDivision:z.enum(['PRIMARY','JUNIOR'])}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Choose Primary or Junior Secondary for this administrator.'});const target=await prisma.user.findUnique({where:{id:req.params.id}});if(!target||target.role!=='ADMIN')return res.status(404).json({error:'Administrator account not found.'});const user=await prisma.user.update({where:{id:target.id},data:{schoolDivision:d.data.schoolDivision}});res.json({user:safeUser(user)})}catch(e){next(e)}});
app.patch('/api/admin/users/:id/password',allow('ADMIN','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const d=z.object({password:z.string().min(12).max(128)}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Set a password with at least 12 characters.'});const target=await prisma.user.findUnique({where:{id:req.params.id},include:{student:{include:{classGroup:true}}}});const division=target?.schoolDivision||target?.student?.classGroup?.division;if(!target||target.role==='SUPER_ADMIN'||req.user.role==='ADMIN'&&(['ADMIN','FINANCE'].includes(target.role)||division!==req.user.schoolDivision))return res.status(404).json({error:'Account not found in your school division.'});const passwordHash=await bcrypt.hash(d.data.password,12);await prisma.user.update({where:{id:target.id},data:{passwordHash}});res.json({ok:true,message:'Password reset. Give the new password to the account holder securely.'})}catch(e){next(e)}});
app.patch('/api/admin/users/:id/status',allow('ADMIN','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const d=z.object({status:z.enum(['ACTIVE','DISABLED'])}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Choose a valid account status.'});const target=await prisma.user.findUnique({where:{id:req.params.id},include:{student:{include:{classGroup:true}}}});const targetDivision=target?.schoolDivision||target?.student?.classGroup?.division;if(!target||target.role==='SUPER_ADMIN'||(req.user.role==='ADMIN'&&(target.role==='ADMIN'||target.role==='FINANCE'||targetDivision!==req.user.schoolDivision)))return res.status(404).json({error:'Account not found in this school division.'});const u=await prisma.user.update({where:{id:req.params.id},data:{status:d.data.status},select:{id:true,name:true,email:true,role:true,status:true,schoolDivision:true}});res.json({user:u})}catch(e){next(e)}});

app.get('/api/portal/notifications',allow('STUDENT','TEACHER','ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),async(req,res,next)=>{try{const audience=req.user.role==='STUDENT'?'STUDENTS':['TEACHER'].includes(req.user.role)?'TEACHERS':req.user.role==='STUDENT'?'STUDENTS':'STAFF';const now=new Date();const items=await prisma.announcement.findMany({where:{published:true,kind:{not:'AD'},audience:{in:['ALL',audience]},AND:[{OR:[{startsAt:null},{startsAt:{lte:now}}]},{OR:[{endsAt:null},{endsAt:{gte:now}}]}]},orderBy:{createdAt:'desc'},take:50});res.json({notifications:items})}catch(e){next(e)}});
app.get('/api/portal/classes/:classId/subjects/:subjectId/learners',allow('TEACHER','ADMIN','SUPER_ADMIN'),async(req,res,next)=>{try{const group=await prisma.classGroup.findUnique({where:{id:req.params.classId},select:{id:true,division:true}});if(!group)return res.status(404).json({error:'Class not found.'});if(req.user.role==='ADMIN'&&(!req.user.schoolDivision||group.division!==req.user.schoolDivision))return res.status(403).json({error:'This class belongs to the other school division.'});if(req.user.role==='TEACHER'){const teacher=await prisma.teacher.findUnique({where:{userId:req.user.id}});const assigned=teacher&&await prisma.classTeaching.findFirst({where:{teacherId:teacher.id,classGroupId:req.params.classId,subjectId:req.params.subjectId}});if(!assigned)return res.status(403).json({error:'You are not assigned to this class and subject.'})}const learners=await prisma.student.findMany({where:{classGroupId:req.params.classId},select:{id:true,admissionNumber:true,user:{select:{name:true}}},orderBy:{user:{name:'asc'}}});res.json({learners})}catch(e){next(e)}});
app.post('/api/portal/grades',allow('TEACHER'),requireCsrf,async(req,res,next)=>{try{const d=z.object({studentId:z.string(),subjectId:z.string(),assessment:z.string().min(1).max(160),score:z.number().min(0),maxScore:z.number().positive(),term:z.string().max(80).optional(),performanceLevel:z.enum(['PL1','PL2','PL3','PL4']).optional(),teacherComment:z.string().max(1500).optional()}).safeParse(req.body);if(!d.success||d.data.score>d.data.maxScore)return res.status(400).json({error:'Check the assessment, score and maximum score.'});const [learner,subject]=await Promise.all([prisma.student.findUnique({where:{id:d.data.studentId},include:{classGroup:true}}),prisma.subject.findUnique({where:{id:d.data.subjectId}})]);if(!learner||!subject||learner.classGroupId!==subject.classGroupId)return res.status(400).json({error:'That learner is not in the selected subject class.'});if(req.user.role==='ADMIN'&&learner.classGroup?.division!==req.user.schoolDivision)return res.status(403).json({error:'This learner belongs to the other school division.'});if(req.user.role==='TEACHER'){const teacher=await prisma.teacher.findUnique({where:{userId:req.user.id}});const assigned=teacher&&await prisma.classTeaching.findFirst({where:{teacherId:teacher.id,classGroupId:learner.classGroupId,subjectId:subject.id}});if(!assigned)return res.status(403).json({error:'You are not assigned to assess this class and subject.'})}const grade=await prisma.grade.create({data:{studentId:learner.id,subjectId:subject.id,assessment:d.data.assessment,score:d.data.score,maxScore:d.data.maxScore,term:d.data.term||null,performanceLevel:d.data.performanceLevel||null,teacherComment:d.data.teacherComment||null,enteredById:req.user.id},include:{subject:true}});res.status(201).json({grade})}catch(e){next(e)}});
app.post('/api/portal/attendance',allow('TEACHER','ADMIN','SUPER_ADMIN'),requireCsrf,async(req,res,next)=>{try{const d=z.object({classGroupId:z.string(),date:z.string().regex(/^\d{4}-\d{2}-\d{2}$/),entries:z.array(z.object({studentId:z.string(),status:z.enum(['PRESENT','LATE','ABSENT','EXCUSED']),note:z.string().max(300).optional()})).min(1).max(300)}).safeParse(req.body);if(!d.success)return res.status(400).json({error:'Choose a class, date and at least one attendance status.'});const group=await prisma.classGroup.findUnique({where:{id:d.data.classGroupId}});if(!group)return res.status(404).json({error:'Class not found.'});if(req.user.role==='ADMIN'&&group.division!==req.user.schoolDivision)return res.status(403).json({error:'This class belongs to the other school division.'});if(req.user.role==='TEACHER'){const teacher=await prisma.teacher.findUnique({where:{userId:req.user.id}});const assigned=teacher&&await prisma.classTeaching.findFirst({where:{teacherId:teacher.id,classGroupId:d.data.classGroupId}});if(!assigned)return res.status(403).json({error:'You are not assigned to this class.'})}const ids=d.data.entries.map(x=>x.studentId);const learners=await prisma.student.findMany({where:{id:{in:ids},classGroupId:d.data.classGroupId},select:{id:true}});if(learners.length!==new Set(ids).size)return res.status(400).json({error:'One or more learners are not in this class.'});const date=new Date(`${d.data.date}T00:00:00.000Z`);const rows=await prisma.$transaction(d.data.entries.map(x=>prisma.attendance.upsert({where:{studentId_date:{studentId:x.studentId,date}},create:{studentId:x.studentId,date,status:x.status,note:x.note||null,markedById:req.user.id},update:{status:x.status,note:x.note||null,markedById:req.user.id}})));res.json({saved:rows.length})}catch(e){next(e)}});
app.get('/api/portal/dashboard',allow('STUDENT','TEACHER','ADMIN','SUPER_ADMIN','FINANCE','BOARDING_MASTER','BOARDING_MISTRESS'),async(req,res,next)=>{try{if(req.user.role==='STUDENT'){const s=await prisma.student.findUnique({where:{userId:req.user.id},include:{classGroup:{include:{classTeaching:{include:{subject:true,teacher:{include:{user:{select:{id:true,name:true,profileImageUrl:true}}}}}}}},feeEntries:true,attendance:{orderBy:{date:'desc'},take:10},grades:{include:{subject:true},orderBy:{createdAt:'desc'},take:12}}});if(!s)return res.json({student:null});const classmateCount=s.classGroupId?await prisma.student.count({where:{classGroupId:s.classGroupId}}):0;const subjectTeachers=s.classGroup?.classTeaching.map(x=>({subject:x.subject.name,teacher:x.teacher.user}))||[];return res.json({student:{...s,classmateCount,subjectTeachers}})}if(req.user.role==='TEACHER'){const teacher=await prisma.teacher.findUnique({where:{userId:req.user.id},include:{classTeaching:{include:{classGroup:{include:{_count:{select:{students:true}}}},subject:true}}}});return res.json({teacher})}const division=req.user.role==='ADMIN'?req.user.schoolDivision:null;if(req.user.role==='ADMIN'&&!division)return res.status(403).json({error:'This administrator has no school division assigned.'});const classFilter=division?{classGroup:{division}}:{};const [students,teachers,classes,events]=await Promise.all([prisma.student.count({where:classFilter}),prisma.teacher.count({where:division?{user:{schoolDivision:division}}:{}}),prisma.classGroup.count({where:division?{division}:{}}),prisma.schoolEvent.findMany({where:{published:true,startsAt:{gte:new Date()}},orderBy:{startsAt:'asc'},take:5})]);res.json({overview:{students,teachers,classes,events,schoolDivision:division}})}catch(e){next(e)}});


app.use((err,req,res,_next)=>{const reference=crypto.randomUUID().slice(0,8);console.error(`[${reference}] ${req.method} ${req.path}`,err);if(res.headersSent)return;let message=err.status?err.message:'The school service could not complete that request.';if(['P1001','P1002','ETIMEDOUT','ECONNREFUSED'].includes(err.code))message='The school database is not reachable. Check DATABASE_URL and the Neon service status in Render.';else if(err.code==='P2021')message='The school database tables are missing. Redeploy the API so Prisma can sync the database schema.';else if(err.code==='P2022')message='The school database schema is out of date. Redeploy the API and review its Prisma deployment logs.';res.status(err.status||500).json({error:message,reference})});
const levelSubjects={
  'Playgroup':['Language activities','Mathematical activities','Environmental activities','Movement and creative activities','Religious education activities'],
  PP1:['Language activities','Mathematical activities','Environmental activities','Movement and creative activities','Religious education activities'],
  PP2:['Language activities','Mathematical activities','Environmental activities','Movement and creative activities','Religious education activities'],
  'Grade 1':['English Activities','Kiswahili','Indigenous Languages','Mathematical Activities','Environmental Activities','Creative Activities','CRE','IRE','HRE'],
  'Grade 2':['English Activities','Kiswahili','Indigenous Languages','Mathematical Activities','Environmental Activities','Creative Activities','CRE','IRE','HRE'],
  'Grade 3':['English Activities','Kiswahili','Indigenous Languages','Mathematical Activities','Environmental Activities','Creative Activities','CRE','IRE','HRE'],
  'Grade 4':['English','Kiswahili or KSL','Mathematics','Science and Technology','Agriculture','Social Studies','Home Science','Creative Arts','Physical and Health Education','CRE','IRE','HRE','Indigenous Language','Arabic','French','German','Mandarin'],
  'Grade 5':['English','Kiswahili or KSL','Mathematics','Science and Technology','Agriculture','Social Studies','Home Science','Creative Arts','Physical and Health Education','CRE','IRE','HRE','Indigenous Language','Arabic','French','German','Mandarin'],
  'Grade 6':['English','Kiswahili or KSL','Mathematics','Science and Technology','Agriculture','Social Studies','Home Science','Creative Arts','Physical and Health Education','CRE','IRE','HRE','Indigenous Language','Arabic','French','German','Mandarin'],
  'Grade 7':['English','Kiswahili','Mathematics','Integrated Science','Agriculture','Social Studies','Creative Arts','Pre-Technical Studies','CRE','IRE','HRE','Indigenous Language','Arabic','French','German','Mandarin'],
  'Grade 8':['English','Kiswahili','Mathematics','Integrated Science','Agriculture','Social Studies','Creative Arts','Pre-Technical Studies','CRE','IRE','HRE','Indigenous Language','Arabic','French','German','Mandarin'],
  'Grade 9':['English','Kiswahili','Mathematics','Integrated Science','Agriculture','Social Studies','Creative Arts','Pre-Technical Studies','CRE','IRE','HRE','Indigenous Language','Arabic','French','German','Mandarin']
};
async function seedGradeGroups(){try{const existing=await prisma.classGroup.findMany({select:{name:true,yearLevel:true}});const known=new Set(existing.map(x=>x.yearLevel||x.name));for(const [level,subjects] of Object.entries(levelSubjects)){if(known.has(level))continue;const division=level==='Playgroup'||level==='PP1'||level==='PP2'||/^Grade [1-6]$/.test(level)?'PRIMARY':'JUNIOR';await prisma.classGroup.create({data:{name:level,yearLevel:level,division,subjects:{create:subjects.map(name=>({name}))}}})}console.log('Elsa grade groups are ready.')}catch(err){console.error('[setup] Could not seed default grade groups:',err)}}
app.listen(port,()=>console.log(`Elsa School API listening on ${port}`));
